mapper.select:
select count(1)
from edu_resource_class_release r
where r.id = #{releaseId}
  and r.binding_id = #{bindingId}
  and r.resource_version_id = #{resourceVersionId}
  and r.ended_at is null
  and r.opens_at <= utc_timestamp(3)
  and (r.closes_at is null or r.closes_at > utc_timestamp(3))

select count(1)
from edu_resource_page
where resource_version_id = #{resourceVersionId}
  and page_no = #{pageNo}

select count(1)
from edu_resource_page
where resource_version_id = #{resourceVersionId}
